<div class="page-head"><div><h1>Banka</h1><div class="sub">Příchozí platby se automaticky párují podle částky, variabilního symbolu a dalších údajů. Nejasné případy můžete spárovat ručně.</div></div><div class="actions"><a class="btn" href="/bank/accounts">Bankovní účty</a></div></div>
<div class="card"><h3>Import výpisu</h3><p class="sub">CSV: datum;částka;měna;protistrana;variabilní_symbol;zpráva</p><form method="post" action="/bank/import" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=App\Core\Auth::csrf()?>"><input type="file" name="csv" accept=".csv" required> <button class="btn primary">Importovat a párovat</button></form></div><div style="height:16px"></div>
<div class="card tablewrap"><table class="table"><tr><th>Datum</th><th>Částka</th><th>Platba od</th><th>VS</th><th>Stav</th><th>Doklad / zákazník</th><th>Akce</th></tr><?php foreach($transactions as $t): $customer=trim(($t['company_name']??'').' '.($t['first_name']??'').' '.($t['last_name']??'')); ?><tr><td><?=\App\Core\View::e($t['booked_at'])?></td><td><?=\App\Core\View::money($t['amount'])?></td><td><?=\App\Core\View::e($t['counterparty'])?></td><td><?=\App\Core\View::e($t['variable_symbol'])?></td><td><span class="badge <?=$t['status']==='matched'?'ok':($t['status']==='suggested'?'':'warn')?>"><?=\App\Core\View::e($t['status']==='matched'?'Spárováno':($t['status']==='suggested'?'Návrh párování':'Čeká na párování'))?></span></td><td><?php if(!empty($t['doc_number'])): ?><b><?=\App\Core\View::e($t['doc_number'])?></b><?php if($customer): ?><div class="sub"><?=\App\Core\View::e($customer)?></div><?php endif; ?><?php else: ?>—<?php endif; ?></td><td><?php if($t['status']!=='matched'): ?><form method="post" action="/bank/match/<?=$t['id']?>" class="bank-match-form"><input type="hidden" name="_csrf" value="<?=App\Core\Auth::csrf()?>"><select name="document_id" required><option value="">Vyberte doklad</option><?php foreach(($matchDocuments??[]) as $d): $name=trim(($d['company_name']??'').' '.($d['first_name']??'').' '.($d['last_name']??'')); ?><option value="<?=$d['id']?>" <?=((int)($t['matched_document_id']??0)===(int)$d['id'])?'selected':''?>><?=\App\Core\View::e($d['doc_number'].' · '.$name.' · '.number_format((float)$d['total_with_vat']-(float)$d['paid'],2,',',' ').' Kč')?></option><?php endforeach; ?></select><button class="btn">Spárovat</button></form><?php else: ?><span class="sub">Hotovo</span><?php endif; ?></td></tr><?php endforeach; ?></table><?php if(!$transactions): ?><p class="sub" style="padding:12px">Zatím nejsou žádné transakce.</p><?php endif; ?></div>